css:
.wrap{display:grid;grid-template-columns:250px 1fr;gap:56px}
.col-l{border-right:1px solid #e6e6e6;padding-right:40px}
.card{background:transparent;border:0;border-radius:0;box-shadow:none;border-right:1px solid #f0f0f0;padding-right:20px}
.card img{border-radius:0}
/* 罫を1カラムとして持つ */
.item{display:grid;grid-template-columns:52px 1px 1fr;column-gap:24px;padding:22px 0}
.item .rule{background:#d8d2c4}
.item .no{font-family:serif;font-size:34px;color:#c9ad6a;line-height:1}
